text:
```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // Hills
  brush.fill("#98FB98", 30);
  brush.beginShape();
  brush.vertex(0, 200);
  brush.vertex(400, 200);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // Clouds
  brush.fill("#F0E68C", 20);
  brush.beginShape();
  brush.vertex(100, 100);
  brush.vertex(200, 150);
  brush.vertex(250, 150);
  brush.vertex(150, 100);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 70);
  brush.beginShape();
  brush.vertex(200, 100);
  brush.vertex(220, 80);
  brush.vertex(240, 100);
  brush.vertex(220, 120);
  brush.endShape(true);
}
```

