  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 100);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Mountains
  brush.fill("#4B0082", 100);
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Hills
  brush.fill("#2E2E2E", 100);
  brush.beginShape();
  brush.vertex(0, 250);
  brush.vertex(400, 250);
  brush.vertex(200, 150);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 200);
  brush.beginShape();
  brush.vertex(150, 100);
  brush.vertex(250, 50);
  brush.vertex(100, 50);
  brush.endShape(true);
}

