  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 100);
  brush.beginShape();
  brush.vertex(100, 150);
  brush.vertex(300, 150);
  brush.vertex(200, 100);
  brush.endShape(true);
}

