  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB", 50);
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);

  // Green hills
  brush.fill("#006400", 70);
  brush.beginShape();
  brush.vertex(0, 300);
  brush.vertex(400, 300);
  brush.vertex(200, 200);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700", 100);
  brush.beginShape();
  brush.vertex(150, 150);
  brush.vertex(250, 100);
  brush.vertex(200, 150);
  brush.endShape(true);
}

